_RAW, _LF, _VC = {}, {}, {}


def _layer(grp, i, f):
  """one layer frame as an 8-bit colorkeyed surface."""
  k = (grp, i, f)
  s = _LF.get(k)
  if s is None:
    raw = _RAW.get((grp, i))
    if raw is None:
      raw = _RAW[(grp, i)] = zlib.decompress(base64.b64decode(LAYERS[grp][i]))
    n = FW * FH
    s = pygame.image.frombuffer(raw[f * n:(f + 1) * n], (FW, FH), 'P')
    s.set_palette(PAL)
    s.set_colorkey(0)
    _LF[k] = s
  return s


def random_villager(rnd=random):
  """a random outfit: tuple of (layer group, index) from the bottom layer up."""
  if rnd.random() < 0.5:
    look = [('mskin', rnd.randrange(5)), ('pants', rnd.randrange(5)), ('mfeet', rnd.randrange(2)),
            ('shirt', rnd.randrange(6)), ('mhair', rnd.randrange(5))]
  else:
    look = [('fskin', rnd.randrange(5))]
    if rnd.random() < 0.6:
      look.append(('socks', rnd.randrange(6)))
    if rnd.random() < 0.7:
      look.append(('ffeet', 0))
    look += [('corset', rnd.randrange(10)), ('skirt', 0), ('fhair', rnd.randrange(5))]
  return tuple(look)


def villager_frame(look, anim, fr, scale=1.25, flip=False):
  """composited villager frame; anim is 'idle', 'walk' or 'run'."""
  first, n = ANIMS[anim]
  f = first + fr % n
  k = (look, f, scale, flip)
  s = _VC.get(k)
  if s is None:
    base = pygame.Surface((FW, FH), pygame.SRCALPHA)
    for grp, i in look:
      base.blit(_layer(grp, i, f), (0, 0))
    if flip:
      base = pygame.transform.flip(base, True, False)
    if scale != 1:
      base = pygame.transform.scale(base, (int(FW * scale), int(FH * scale)))
    if len(_VC) > 700:
      _VC.clear()
    _VC[k] = s = base
  return s

